head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > E > onmouseover]<br/>Image 영역 내로 마우스 포인터가 들어 왔을 때 발생합니다.",
    "validation" : [
        "Image 영역 내로 마우스 포인터가 들어 왔을 때 발생합니다.",
        "이벤트 객체 e (MouseEvent) 가 핸들러에 전달되어야 합니다.",
        "Event Object 의 설명은 표준 속성만을 다루고 있으며 웹브라우저에 따라 일부 차이가 있을 수 있습니다.",
        "컴포넌트가 비활성화(disabled)상태이면 이벤트가 발생하지 않습니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 값 조회
    let cDisabled = con_disabled.getText();

    // 테스트 참고 라벨
    let strLabel = "";
    strLabel += "[전제] disabled = " + (cDisabled === "" ? "미설정" : cDisabled);
    strLabel += " (조건 변경 후 Target 재생성 버튼 클릭)\n";
    strLabel += "[절차] 마우스 포인터를 image 영역 밖에 둔 뒤 image 영역 안으로 이동시켜 봅니다.\n";
    strLabel += "[확인] 리턴 값 확인 영역에 onmouseover 이벤트 발생 로그가 출력되는지 확인합니다.";

    await $c.gcm.createLabel('label="' + strLabel + '"', '', 'label1');

    // 조건 설정
    let properties = {
        disabled : cDisabled,
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onmouseover"]);

    // comp 생성 함수 호출
    await $c.gcm.createBasicImage(cList, eList);
}



// validation 1, 2, 3, 4 판정 출력
scwin.target1_onmouseover = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onmouseover 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
}
